import React from 'react';
import './App.css';
import Shell from './Shell';
import CharacterList from './CharacterList';

function App() {
  return (
    <Shell
      titulo="Los personajes más legendarios de Star Wars"
      descripcion="Datos obtenidos en tiempo real desde la API pública SWAPI mediante una petición Ajax con Axios."
    >
      <CharacterList />
    </Shell>
  );
}

export default App;
